package org.json;
import java.util.*;
public class JSONObject { Map<String,Object> m=new LinkedHashMap<>(); public JSONObject(){} public JSONObject(String s){ m.put("Status",0); JSONArray a=new JSONArray(); for (String part: s.split("\\{")) if (part.contains("\"type\"")) { JSONObject o=new JSONObject(); java.util.regex.Matcher t=java.util.regex.Pattern.compile("\"type\"\\s*:\\s*(\\d+)").matcher(part); if(t.find()) o.m.put("type",Integer.parseInt(t.group(1))); t=java.util.regex.Pattern.compile("\"TTL\"\\s*:\\s*(\\d+)").matcher(part); if(t.find()) o.m.put("TTL",Long.parseLong(t.group(1))); t=java.util.regex.Pattern.compile("\"data\"\\s*:\\s*\"([^\"]+)\"").matcher(part); if(t.find()) o.m.put("data",t.group(1)); a.put(o);} m.put("Answer",a);} public JSONObject put(String k,Object v){m.put(k,v);return this;} public Object get(String k){return m.get(k);} public boolean has(String k){return m.containsKey(k);} public int optInt(String k,int d){Object v=m.get(k);return v instanceof Number?((Number)v).intValue():d;} public long optLong(String k,long d){Object v=m.get(k);return v instanceof Number?((Number)v).longValue():d;} public long optLong(String k){return optLong(k,0);} public String optString(String k,String d){Object v=m.get(k);return v==null?d:String.valueOf(v);} public String optString(String k){return optString(k,"");} public boolean optBoolean(String k){Object v=m.get(k);return Boolean.TRUE.equals(v);} public JSONArray optJSONArray(String k){Object v=m.get(k);return v instanceof JSONArray?(JSONArray)v:null;} public JSONObject optJSONObject(String k){Object v=m.get(k);return v instanceof JSONObject?(JSONObject)v:null;} public Iterator<String> keys(){return m.keySet().iterator();} public String toString(){return m.toString();} }
